    eligibility: "融資申請日を基準に婚姻届出から7年以内、または6か月以内に結婚予定の新婚(予定)夫婦で、夫婦合算年所得9,700万ウォン以下であり、本人と配偶者がともに無住宅者である必要がありました。",
    support_content: "賃貸保証金7億ウォン以下の住宅について、保証金の90%以内、最大2億ウォンまで融資利子を支援しました。",
