  "customized-care-service-for-elderly": {
    title: "高齢者オーダーメイドケアサービス",
    summary: "独居・低所得などケアが必要な高齢者に安否確認、家事支援、病院同行などを無料で提供するサービスです。",
    eligibility: "満65歳以上のうち国民基礎生活受給者、次上位階層、または基礎年金受給者として低所得・独居・脆弱な高齢者が対象です。本人だけでなく家族・隣人・公務員も代わりに申請できます。",
    support_content: "定期安否確認、安全点検、家事支援、病院同行、文化・余暇活動、栄養・健康管理教育を自己負担なく全額無料で提供します。2026年からはAIセンサー・スマートウォッチを活用したデジタルケアと退院後の集中ケアも強化されます。",
    application_method: "住所地管轄の邑・面・洞住民センターに申請書を提出すると、遂行機関の専任社会福祉士が訪問相談を行います。受付日から公休日を除き30日以内(最大30日延長可能)に資格決定結果を書面で通知されます。",
    required_documents: ["身分証"],
    checklist: ["家族が代わりに申請する場合、関係を確認できる書類が追加で必要になる場合があります", "危機世帯は申請手続きが簡素化され、より速く支援を受けられます"],
    faq: [{ question: "年齢は満年齢基準ですか?", answer: "はい、満65歳以上を基準とし、通常は公告日または申請日を基準に計算します。正確な基準日は公式公告文で改めてご確認ください。" }, { question: "随時申請は可能ですか?", answer: "はい、この制度には特別な締め切りがなく随時申請できます。ただし予算が消化されると早期に締め切られる場合があるため、できるだけ早く申請することをお勧めします。" }, { question: "他の支援金と重複して受けられますか?", answer: "制度ごとに重複受給の可否が異なります。保健福祉部・独居高齢者総合支援センターにお問い合わせのうえ、他の支援金と併せて受給できるか確認することをお勧めします。" }],
  },
  "dementia-screening-treatment-cost-support": {
    title: "認知症検診および認知症治療管理費支援事業",
    summary: "認知症安心センターを通じて高齢者の認知症検診費用と治療・薬剤費を支援する制度です。",
    eligibility: "検診費支援は満60歳以上基準中位所得120%以下(自治体によって緩和運営)、治療管理費支援は満60歳以上の認知症患者のうち基準中位所得140%以下が対象です。",
    support_content: "診断検査は1人当たり最大15万ウォン、鑑別検査は医療機関種別ごとに1人当たり最大11万ウォンまで支援します。認知症治療管理費(薬剤費・診療費自己負担)は月最大3万ウォン、年間最大36万ウォンまで支援を受けられます。",
    application_method: "住民登録住所地管轄の保健所内の認知症安心センターを訪問して申請します。",
    required_documents: ["身分証", "診断書または所見書(治療管理費支援時)"],
    checklist: ["検診費と治療管理費はそれぞれ別途申請する必要があります", "所得基準は自治体ごとに異なって運営される場合があるため、管轄の認知症安心センターで改めてご確認ください"],
    faq: [{ question: "所得基準はどのように確認しますか?", answer: "検診費は中位所得120%以下/治療管理費は中位所得140%以下(自治体ごとに差があります)の条件を満たす必要があります。正確な所得算定方法は、福祉ロ(ボクジロ)の模擬計算または担当機関へのお問い合わせで確認することをお勧めします。" }, { question: "年齢は満年齢基準ですか?", answer: "はい、満60歳以上を基準とし、通常は公告日または申請日を基準に計算します。正確な基準日は公式公告文で改めてご確認ください。" }, { question: "随時申請は可能ですか?", answer: "はい、この制度には特別な締め切りがなく随時申請できます。ただし予算が消化されると早期に締め切られる場合があるため、できるだけ早く申請することをお勧めします。" }],
  },
